/** `edu brain status|recall|read|remember|share|maintain|tidy|lint|import|link|proposals|approve`. */
import { join, resolve } from 'node:path';
import type { Command } from 'commander';
import { autoMaintain } from '../../brain/auto-maintain.js';
import { compileReportLines } from '../../brain/compile.js';
import { listCanonicalProposals, reviewCanonicalProposals } from '../../brain/proposals.js';
import { LINT_KINDS, lintBrain, type LintReport } from '../../brain/lint.js';
import { brainPath, isInside } from '../../brain/location.js';
import { TIDY_KINDS, applyTidy, loadTidyPlan, planTidy, saveTidyPlan } from '../../brain/tidy.js';
import type { ClaimBand, TransitiveKind } from '../../core/contracts.js';
import type { CliContext } from '../context.js';
import { t, type Lang } from '../i18n.js';
import { action, look, parseIntOption, printJson } from '../kit.js';
import { brainDir, createVaultLink, linkPath } from '../link.js';
import { exists, lessonCount, openWorkspace, type Workspace } from '../workspace.js';

const KINDS: TransitiveKind[] = ['decision', 'hypothesis', 'commitment', 'lesson'];
const BANDS: ClaimBand[] = ['verified', 'inferred', 'hypothesis'];

function oneOf<T extends string>(value: string, allowed: readonly T[], flag: string): T {
  if (!(allowed as readonly string[]).includes(value)) throw new Error(`${flag} must be one of ${allowed.join(', ')}, got "${value}"`);
  return value as T;
}

/** Opens the workspace and requires an initialized primary brain (writes go there). */
async function writableWorkspace(ctx: CliContext, cwd: string, lang: Lang): Promise<Workspace> {
  const ws = await openWorkspace(ctx, cwd);
  if (!(await exists(join(ws.primary.root, 'EDU.md')))) {
    throw new Error(lang === 'es' ? 'No hay cerebro inicializado — ejecuta: edu init' : 'No brain found — run: edu init');
  }
  return ws;
}

const REVIEW = {
  en: {
    none: 'Nothing to approve: no proposed canonical notes.',
    header: '{count} proposed canonical note(s) waiting for you:',
    hint: 'Approve: edu brain approve <id> | --all   ·   Reject: edu brain approve --reject <id>',
    accepted: 'Accepted {id}',
    rejected: 'Rejected {id} (deleted; recorded in episodic)',
    failed: 'Could not review {id}: {error}',
    nothing: 'Say what to review: edu brain approve <id...> | --all | --reject <id>',
    summary: '{accepted} accepted · {rejected} rejected · {errors} error(s)',
  },
  es: {
    none: 'Nada que aprobar: no hay notas canónicas propuestas.',
    header: '{count} nota(s) canónica(s) propuesta(s) esperan tu aprobación:',
    hint: 'Aprobar: edu brain approve <id> | --all   ·   Rechazar: edu brain approve --reject <id>',
    accepted: 'Aceptada {id}',
    rejected: 'Rechazada {id} (borrada; queda registro en episodic)',
    failed: 'No se pudo revisar {id}: {error}',
    nothing: 'Indica qué revisar: edu brain approve <id...> | --all | --reject <id>',
    summary: '{accepted} aceptadas · {rejected} rechazadas · {errors} error(es)',
  },
} as const;
const fill = (text: string, vars: Record<string, string | number>) => text.replace(/\{(\w+)\}/g, (_, key: string) => String(vars[key] ?? `{${key}}`));
const collect = (value: string, previous: string[]) => [...previous, value];

interface ApproveOpts { all?: boolean; reject?: string[]; reason?: string; json?: boolean }

interface RecallOpts { limit?: string; json?: boolean; alt?: string[] }
interface RememberOpts { kind?: string; body?: string; band?: string; due?: string; json?: boolean }

export function registerBrain(program: Command, ctx: CliContext): void {
  const brain = program.command('brain').description('inspect and grow the second brain');

  brain
    .command('status')
    .description('notes per tier, kind and status')
    .option('--json', 'machine-readable output')
    .action(
      action<{ json?: boolean }>(ctx, async ({ g, opts }) => {
        const ws = await openWorkspace(ctx, g.cwd);
        const stats = await ws.brain.stats();
        if (g.json || opts.json) return printJson(ctx, { locations: ws.locations, ...stats });
        const { glyphs } = look(ctx);
        ctx.out(`${glyphs.brain} ${stats.total} notes ${glyphs.sep} ${lessonCount(stats.byStatus)} lessons`);
        for (const loc of ws.locations) ctx.out(`  ${loc.scope.padEnd(8)} ${loc.root}`);
        ctx.out(`  canonical ${stats.byTier.canonical} ${glyphs.sep} episodic ${stats.byTier.episodic} ${glyphs.sep} transitive ${stats.byTier.transitive}`);
        const kinds = Object.entries(stats.byKind).sort(([a], [b]) => a.localeCompare(b));
        if (kinds.length) ctx.out(`  ${kinds.map(([k, n]) => `${k} ${n}`).join(` ${glyphs.sep} `)}`);
      }),
    );

  brain
    .command('recall')
    .description('search the brain (relevance × learned weight)')
    .argument('<query...>', 'what to look for')
    .option('--alt <query>', 'the same question rephrased or translated, fused with it (repeatable, up to 3)', collect, [])
    .option('--limit <n>', 'maximum hits', '8')
    .option('--json', 'machine-readable output')
    .action(
      action<RecallOpts>(ctx, async ({ g, opts }, query) => {
        const alt = opts.alt ?? [];
        if (alt.length > 3) throw new Error('--alt accepts at most 3 phrasings');
        const ws = await openWorkspace(ctx, g.cwd);
        const hits = await ws.brain.recall(alt.length ? [query ?? '', ...alt] : query ?? '', { limit: parseIntOption(opts.limit ?? '8', '--limit') });
        if (g.json || opts.json) {
          return printJson(ctx, hits.map((h) => ({ id: h.note.meta.id, title: h.note.meta.title, tier: h.note.meta.tier, band: h.note.meta.band, score: h.score, why: h.why })));
        }
        if (!hits.length) return ctx.out(t(g.lang, 'brain.empty'));
        for (const hit of hits) {
          const band = hit.note.meta.band ? ` [${hit.note.meta.band}]` : '';
          ctx.out(`${hit.score.toFixed(2).padStart(6)}  ${hit.note.meta.id}${band}  ${hit.note.meta.title}`);
          ctx.out(`        ${hit.why}`);
        }
      }),
    );

  brain
    .command('read')
    .description('print a note: id, legacy id or alias (D-010), unique id prefix, filename or exact title')
    .argument('<reference...>', 'what the note is called')
    .option('--json', 'machine-readable output')
    .action(
      action<{ json?: boolean }>(ctx, async ({ g, opts, cmd }) => {
        const reference = (cmd.args as string[]).join(' ').trim();
        const ws = await openWorkspace(ctx, g.cwd);
        const result = await ws.brain.resolve(reference);
        const json = g.json || opts.json;
        if (!result) {
          ctx.setExitCode(1);
          return json ? printJson(ctx, { reference, found: false }) : ctx.err(t(g.lang, 'brain.readMissing', { reference }));
        }
        if ('candidates' in result) {
          ctx.setExitCode(1);
          if (json) return printJson(ctx, { reference, ambiguous: true, via: result.via, candidates: result.candidates.map((n) => ({ id: n.meta.id, title: n.meta.title, legacy_id: n.meta.legacy_id })) });
          ctx.out(t(g.lang, 'brain.readAmbiguous', { reference, via: result.via, count: result.candidates.length }));
          for (const n of result.candidates) ctx.out(`  ${n.meta.id}  ${n.meta.title}`);
          return;
        }
        const { note, via } = result;
        if (json) return printJson(ctx, { via, id: note.meta.id, path: note.path, meta: note.meta, body: note.body });
        const { glyphs } = look(ctx);
        ctx.out(`${note.meta.id} ${glyphs.sep} ${note.meta.title}${note.meta.status ? ` ${glyphs.sep} ${note.meta.status}` : ''}${note.meta.band ? ` [${note.meta.band}]` : ''}`);
        ctx.out(note.path);
        ctx.out('');
        ctx.out(note.body);
      }),
    );

  brain
    .command('remember')
    .description('write a decision, hypothesis, commitment or lesson')
    .argument('<title...>', 'one-line title')
    .option('--kind <kind>', KINDS.join(' | '), 'lesson')
    .option('--body <text>', 'markdown body')
    .option('--band <band>', BANDS.join(' | '))
    .option('--due <date>', 'due date for commitments (YYYY-MM-DD)')
    .option('--json', 'machine-readable output')
    .action(
      action<RememberOpts>(ctx, async ({ g, opts }, title) => {
        const kind = oneOf(opts.kind ?? 'lesson', KINDS, '--kind');
        const band = opts.band ? oneOf(opts.band, BANDS, '--band') : undefined;
        const ws = await writableWorkspace(ctx, g.cwd, g.lang);
        // remember = write + compile: related notes are linked and likely contradictions reported.
        const { note, report } = await ws.brain.remember({
          tier: 'transitive',
          kind,
          title: (title ?? '').trim(),
          body: opts.body ?? '',
          source: 'user',
          ...(band ? { band } : {}),
          ...(opts.due ? { due: opts.due } : {}),
        });
        if (g.json || opts.json) return printJson(ctx, { id: note.meta.id, path: note.path, report });
        ctx.out(t(g.lang, 'brain.remembered', { id: note.meta.id }));
        for (const line of compileReportLines(report)) ctx.out(`  ${line}`);
      }),
    );

  brain
    .command('share')
    .description('move a note to the shared global brain (default) or back to this project, keeping its id')
    .argument('<id>', 'note id, alias, unique prefix or exact title')
    .option('--to <scope>', 'global | project', 'global')
    .option('--json', 'machine-readable output')
    .action(
      action<{ to?: string; json?: boolean }>(ctx, async ({ g, opts }, reference) => {
        const scope = oneOf(opts.to ?? 'global', ['global', 'project'] as const, '--to');
        const ws = await openWorkspace(ctx, g.cwd);
        const target = ws.locations.find(loc => loc.scope === scope);
        const es = g.lang === 'es';
        if (!target || !(await exists(join(target.root, 'EDU.md')))) {
          throw new Error(scope === 'global'
            ? (es ? 'No hay cerebro global inicializado — ejecuta: edu init --global' : 'No global brain found — run: edu init --global')
            : (es ? 'No hay cerebro de proyecto aquí — ejecuta: edu init' : 'No project brain here — run: edu init'));
        }
        const result = await ws.brain.resolve(reference ?? '');
        if (!result) throw new Error(t(g.lang, 'brain.readMissing', { reference: reference ?? '' }));
        if ('candidates' in result) throw new Error(`${t(g.lang, 'brain.readAmbiguous', { reference: reference ?? '', via: result.via, count: result.candidates.length })} ${result.candidates.map(note => note.meta.id).join(', ')}`);
        const from = ws.locations.find(loc => isInside(brainPath(loc), result.note.path))?.scope ?? ws.primary.scope;
        const moved = await ws.brain.move(result.note.meta.id, target.root);
        if (g.json || opts.json) return printJson(ctx, { id: moved.meta.id, from, to: scope, path: moved.path });
        ctx.out(es ? `Compartida ${moved.meta.id}: ${from} → ${scope} (${moved.path})` : `Shared ${moved.meta.id}: ${from} → ${scope} (${moved.path})`);
      }),
    );

  brain
    .command('maintain')
    .description('decay, promote/retire lessons, flag overdue commitments, rebuild the index')
    .option('--json', 'machine-readable output')
    .action(
      action<{ json?: boolean }>(ctx, async ({ g, opts }) => {
        const ws = await writableWorkspace(ctx, g.cwd, g.lang);
        const result = await autoMaintain(ws.brain, ws.primary.root, { force: true });
        if (!result.ran) throw new Error(result.reason);
        const { report } = result;
        if (g.json || opts.json) return printJson(ctx, report);
        ctx.out(t(g.lang, 'brain.maintained', { changed: report.changed.length, promoted: report.promoted.length, retired: report.retired.length, overdue: report.overdue.length }));
      }),
    );

  brain
    .command('tidy')
    .description('plan what maintenance never cleans (empty sessions, stale hypotheses, broken links with a known target); --apply runs the reviewed plan with a backup')
    .option('--apply', 'apply the saved plan (edit it first to drop what you do not want)')
    .option('--only <kinds>', `with --apply: comma list of ${TIDY_KINDS.join(', ')}`)
    .option('--stale-days <n>', 'age in days after which an open hypothesis is proposed as no-evidence', '30')
    .option('--json', 'machine-readable output')
    .action(
      action<{ apply?: boolean; only?: string; staleDays?: string; json?: boolean }>(ctx, async ({ g, opts }) => {
        const ws = await writableWorkspace(ctx, g.cwd, g.lang);
        if (opts.apply) {
          const plan = await loadTidyPlan(ws.primary);
          if (!plan) throw new Error(t(g.lang, 'brain.tidyNoPlan'));
          const only = opts.only?.split(',').map(kind => oneOf(kind.trim(), TIDY_KINDS, '--only'));
          const result = await applyTidy(ws.brain, ws.primary, plan, { only });
          if (g.json || opts.json) return printJson(ctx, result);
          ctx.out(t(g.lang, 'brain.tidyApplied', { sessions: result.sessions, hypotheses: result.hypotheses, aliases: result.aliases, skipped: result.skipped.length, backup: result.backup }));
          for (const skip of result.skipped) ctx.out(`  - ${skip.id}: ${skip.reason}`);
          return;
        }
        const staleDays = parseIntOption(opts.staleDays ?? '30', '--stale-days');
        const plan = await planTidy(ws.brain, ws.primary, { staleDays });
        const path = await saveTidyPlan(ws.primary, plan);
        if (g.json || opts.json) return printJson(ctx, { ...plan, path });
        if (!plan.sessions.length && !plan.hypotheses.length && !plan.aliases.length && !plan.manual.length) return ctx.out(t(g.lang, 'brain.tidyNothing'));
        ctx.out(t(g.lang, 'brain.tidyPlan', { sessions: plan.sessions.length, hypotheses: plan.hypotheses.length, days: staleDays, aliases: plan.aliases.length, manual: plan.manual.length, unresolved: plan.unresolved }));
        for (const h of plan.hypotheses) ctx.out(`  H ${h.created.slice(0, 10)} ${h.title}`);
        for (const a of plan.aliases) ctx.out(`  A ${a.id} ← ${a.add.join(', ')}`);
        for (const m of plan.manual) ctx.out(`  ! [[${m.link}]] → ${m.target} (${m.reason})`);
        ctx.out(t(g.lang, 'brain.tidySaved', { path }));
      }),
    );

  brain
    .command('lint')
    .description('read-only health check: orphans, missing pages, possible contradictions, stale claims, overdue commitments, duplicates')
    .option('--stale-days <n>', 'age in days after which a time-sensitive claim without "(as of YYYY-MM-DD)" is stale', '90')
    .option('--strict', 'exit with code 1 when a finding has severity error')
    .option('--json', 'machine-readable output')
    .action(
      action<{ staleDays?: string; strict?: boolean; json?: boolean }>(ctx, async ({ g, opts }) => {
        const ws = await openWorkspace(ctx, g.cwd);
        const staleDays = parseIntOption(opts.staleDays ?? '90', '--stale-days');
        const report = await lintBrain(ws.brain, { staleDays, root: brainPath(ws.primary) });
        if (opts.strict && report.summary.error) ctx.setExitCode(1);
        if (g.json || opts.json) return printJson(ctx, report);
        for (const line of lintTable(report)) ctx.out(line);
      }),
    );

  brain
    .command('import')
    .description('import an Albert vault or MORAGENT memory (read-only on the source)')
    .argument('<source>', 'albert | moragent')
    .argument('<path>', 'source directory')
    .option('--json', 'machine-readable output')
    .action(
      action<{ json?: boolean }>(ctx, async ({ g, opts }, source, path) => {
        const kind = oneOf(source ?? '', ['albert', 'moragent'] as const, 'source');
        const ws = await writableWorkspace(ctx, g.cwd, g.lang);
        const { importAlbert, importMoragent } = await import('../../brain/index.js');
        const report = await (kind === 'albert' ? importAlbert : importMoragent)(resolve(g.cwd, path ?? ''), ws.brain);
        if (g.json || opts.json) return printJson(ctx, { imported: report.imported.map((n) => n.meta.id), skipped: report.skipped, errors: report.errors, warnings: report.warnings });
        ctx.out(t(g.lang, 'brain.imported', { imported: report.imported.length, skipped: report.skipped.length, errors: report.errors.length, warnings: report.warnings.length }));
        for (const warning of report.warnings) ctx.err(`  ${t(g.lang, 'brain.importWarning', { warning })}`);
        for (const error of report.errors) ctx.err(`  ${error}`);
      }),
    );

  brain
    .command('link')
    .description('link the brain into an Obsidian vault as <vault>/Edu/<project>')
    .argument('<vault>', 'Obsidian vault directory')
    .action(
      action(ctx, async ({ g }, vault) => {
        const ws = await writableWorkspace(ctx, g.cwd, g.lang);
        const vaultPath = resolve(g.cwd, vault ?? '');
        const link = linkPath(vaultPath, ws.primary);
        const target = brainDir(ws.primary);
        let outcome: 'created' | 'exists';
        try {
          outcome = await createVaultLink(link, target);
        } catch (error) {
          if ((error as { code?: string }).code === 'ELINKCONFLICT') throw new Error(t(g.lang, 'brain.linkConflict', { link }));
          throw error;
        }
        const configPath = join(ws.primary.root, 'config.json');
        if (await exists(configPath)) {
          const { loadConfig, saveConfig } = await import('../../orchestrator/config.js');
          const config = await loadConfig(configPath);
          await saveConfig(configPath, { ...config, brain: { ...config.brain, obsidianVault: vaultPath } });
        }
        ctx.out(t(g.lang, outcome === 'created' ? 'brain.linked' : 'brain.linkExists', { link, target }));
      }),
    );

  brain
    .command('proposals')
    .description('canonical notes proposed for your approval (title, source, band, why)')
    .option('--json', 'machine-readable output')
    .action(
      action<{ json?: boolean }>(ctx, async ({ g, opts }) => {
        const ws = await openWorkspace(ctx, g.cwd);
        const items = await listCanonicalProposals(ws.brain);
        if (g.json || opts.json) return printJson(ctx, items);
        const m = REVIEW[g.lang];
        if (!items.length) return ctx.out(m.none);
        const { glyphs } = look(ctx);
        ctx.out(fill(m.header, { count: items.length }));
        for (const p of items) {
          ctx.out(`  ${p.id}  ${p.title}`);
          ctx.out(`      ${p.band} ${glyphs.sep} ${p.source} ${glyphs.sep} ${p.why}`);
        }
        ctx.out('');
        ctx.out(m.hint);
      }),
    );

  brain
    .command('approve')
    .description('accept proposed canonical notes (ids or --all) or reject them (--reject <id>, repeatable)')
    .argument('[ids...]', 'proposal ids to accept (see: edu brain proposals)')
    .option('--all', 'accept every pending proposal (except those passed to --reject)')
    .option('--reject <id>', 'reject a proposal: deleted, with a record in episodic memory (repeatable)', collect, [])
    .option('--reason <text>', 'why the rejected proposals were wrong (kept in the record)')
    .option('--json', 'machine-readable output')
    .action(
      action<ApproveOpts>(ctx, async ({ g, opts, cmd }) => {
        const ids = (cmd.args as string[]).filter(Boolean);
        const reject = opts.reject ?? [];
        const m = REVIEW[g.lang];
        if (!ids.length && !opts.all && !reject.length) throw new Error(m.nothing);
        const ws = await openWorkspace(ctx, g.cwd);
        const result = await reviewCanonicalProposals(ws.brain, { approve: ids, all: Boolean(opts.all), reject, reason: opts.reason });
        if (result.accepted.length || result.rejected.length) await ws.brain.rebuildIndex();
        if (result.errors.length) ctx.setExitCode(1);
        if (g.json || opts.json) return printJson(ctx, result);
        if (!result.accepted.length && !result.rejected.length && !result.errors.length) return ctx.out(m.none);
        for (const id of result.accepted) ctx.out(fill(m.accepted, { id }));
        for (const id of result.rejected) ctx.out(fill(m.rejected, { id }));
        for (const e of result.errors) ctx.err(fill(m.failed, e));
        ctx.out(fill(m.summary, { accepted: result.accepted.length, rejected: result.rejected.length, errors: result.errors.length }));
      }),
    );
}

/** Findings grouped by kind (most actionable first), then the summary counts. */
export function lintTable(report: LintReport): string[] {
  const lines: string[] = [];
  for (const kind of LINT_KINDS) {
    const group = report.findings.filter(finding => finding.kind === kind);
    if (!group.length) continue;
    lines.push(`${kind} (${group.length})`);
    for (const finding of group) {
      lines.push(`  ${finding.severity.padEnd(7)} ${finding.ids.join(', ')}`);
      lines.push(`          ${finding.message}`);
      lines.push(`          fix: ${finding.fix}`);
    }
    lines.push('');
  }
  const { summary } = report;
  if (!summary.total) lines.push(`No findings in ${report.notes} notes.`);
  else lines.push(`${summary.total} finding(s) in ${report.notes} notes: ${summary.error} error · ${summary.warning} warning · ${summary.info} info — ${LINT_KINDS.filter(kind => summary[kind]).map(kind => `${kind} ${summary[kind]}`).join(', ')}`);
  return lines;
}
